namespace Liberu\ControlPanel\AccountsFilament\Resources;
use Filament\Resources\Resource; use Filament\Schemas\Schema; use Filament\Tables\Columns\TextColumn; use Filament\Tables\Table; use Illuminate\Database\Eloquent\Builder; use Liberu\ControlPanel\Accounts\Models\AccountDelegation;
final class AccountDelegationResource extends Resource { protected static ?string $model=AccountDelegation::class; protected static string|\BackedEnum|null $navigationIcon='heroicon-o-user-minus'; protected static string|\UnitEnum|null $navigationGroup='Control Panel'; public static function form(Schema $schema):Schema{return $schema->components([]);} public static function table(Table $table):Table{return $table->columns([TextColumn::make('delegate_id')->searchable(),TextColumn::make('account_id'),TextColumn::make('active')->badge(),TextColumn::make('expires_at')->dateTime()])->defaultSort('created_at','desc');} public static function getEloquentQuery():Builder{return parent::getEloquentQuery()->where('team_id',auth()->user()?->current_team_id);} public static function getPages():array{return ['index'=>Pages\ListAccountDelegations::route('/')];} }
